#include <iostream>
#include <iomanip>
#include <stdexcept>

class Time {
private:
    int hour{0};
    int minute{0};
    int second{0};

public:
    Time() = default;

    void setTime(int h, int m, int s) {
        if ((h >= 0 && h < 24) && (m >= 0 && m < 60) && (s >= 0 && s < 60)) {
            hour = h;
            minute = m;
            second = s;
        } else {
            throw std::invalid_argument("hour, minute and/or second was out of range");
        }
    }

    void printUniversal() const {
        std::cout << std::setfill('0') << std::setw(2) << hour << ":"
                  << std::setw(2) << minute << ":"
                  << std::setw(2) << second;
    }

    void printStandard() const {
        std::cout << ((hour == 0 || hour == 12) ? 12 : hour % 12) << ":"
                  << std::setfill('0') << std::setw(2) << minute << ":"
                  << std::setw(2) << second
                  << (hour < 12 ? " AM" : " PM");
    }
};

int main() {
    Time t;
    t.printUniversal();
    std::cout << " | ";
    t.printStandard();
    std::cout << "\n";

    t.setTime(13, 5, 9);
    t.printUniversal();
    std::cout << " | ";
    t.printStandard();
    std::cout << "\n";

    return 0;
}

#include <iostream>
#include <iomanip>
#include <stdexcept>
#include <array>

class Time {
private:
    int hour{0};
    int minute{0};
    int second{0};

public:
    Time() = default;

    void setTime(int h, int m, int s) {
        if ((h >= 0 && h < 24) && (m >= 0 && m < 60) && (s >= 0 && s < 60)) {
            hour = h;
            minute = m;
            second = s;
        } else {
            throw std::invalid_argument("hour, minute and/or second was out of range");
        }
    }

    void printUniversal() const {
        std::cout << std::setfill('0') << std::setw(2) << hour << ":"
                  << std::setw(2) << minute << ":"
                  << std::setw(2) << second;
    }

    void printStandard() const {
        std::cout << ((hour == 0 || hour == 12) ? 12 : hour % 12) << ":"
                  << std::setfill('0') << std::setw(2) << minute << ":"
                  << std::setw(2) << second
                  << (hour < 12 ? " AM" : " PM");
    }
};

int main() {
    Time t;
    std::cout << "Initial universal time: ";
    t.printUniversal();
    std::cout << "\nInitial standard time: ";
    t.printStandard();
    std::cout << "\n";

    t.setTime(13, 27, 6);
    std::cout << "Universal time after setTime: ";
    t.printUniversal();
    std::cout << "\nStandard time after setTime: ";
    t.printStandard();
    std::cout << "\n";

    try {
        t.setTime(99, 99, 99);
    } catch (const std::invalid_argument& e) {
        std::cout << "Exception caught: " << e.what() << "\n";
    }

    std::cout << "After invalid setTime attempt: ";
    t.printUniversal();
    std::cout << "\n";

    return 0;
}
